 1	public final class FloydWarshall {
 2	    public static final int INF = 100_000_000;
 3	
 4	    private FloydWarshall() {
 5	    }
 6	
 7	    public static int[][] shortestPaths(int[][] graph) {
 8	        validateSquareMatrix(graph);
 9	
10	        int vertexCount = graph.length;
11	        int[][] distances = copyMatrix(graph);
12	
13	        for (int intermediate = 0; intermediate < vertexCount; intermediate++) {
14	            for (int source = 0; source < vertexCount; source++) {
15	                for (int target = 0; target < vertexCount; target++) {
16	                    if (distances[source][intermediate] == INF
17	                            || distances[intermediate][target] == INF) {
18	                        continue;
19	                    }
20	
21	                    int candidateDistance = addDistances(
22	                            distances[source][intermediate],
23	                            distances[intermediate][target]);
24	                    if (candidateDistance < distances[source][target]) {
25	                        distances[source][target] = candidateDistance;
26	                    }
27	                }
28	            }
29	        }
30	
31	        return distances;
32	    }
33	
34	    public static boolean hasNegativeCycle(int[][] distances) {
35	        validateSquareMatrix(distances);
36	
37	        for (int vertex = 0; vertex < distances.length; vertex++) {
38	            if (distances[vertex][vertex] < 0) {
39	                return true;
40	            }
41	        }
42	
43	        return false;
44	    }
45	
46	    private static int[][] copyMatrix(int[][] matrix) {
47	        int[][] copy = new int[matrix.length][matrix.length];
48	        for (int row = 0; row < matrix.length; row++) {
49	            System.arraycopy(matrix[row], 0, copy[row], 0, matrix.length);
50	        }
51	        return copy;
52	    }
