54	    private static int addDistances(int firstDistance, int secondDistance) {
55	        try {
56	            return Math.addExact(firstDistance, secondDistance);
57	        } catch (ArithmeticException exception) {
58	            throw new ArithmeticException("Path distance overflowed int range.");
59	        }
60	    }
