62	    private static void validateSquareMatrix(int[][] matrix) {
63	        if (matrix == null) {
64	            throw new IllegalArgumentException("Graph matrix cannot be null.");
65	        }
66	
67	        for (int row = 0; row < matrix.length; row++) {
68	            if (matrix[row] == null || matrix[row].length != matrix.length) {
69	                throw new IllegalArgumentException("Graph matrix must be square.");
70	            }
71	        }
72	    }
